contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v1, uint v2) public {
        require(v1 != v2);

        // Before initialization, MinSum can be set freely
        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        require(c.MinSum() == v1);

        c.Initialized(); if (__ESBMC_reverted()) return;

        // After initialization, SetMinSum must revert for any value
        bool reverted;
        c.SetMinSum(v2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && c.MinSum() == v1);
    }
}

