// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 v1, uint256 v2) internal {
        vm.assume(v1 != v2);
        try c.SetMinSum(v1) {} catch { return; }
        v1 = c.MinSum();
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(v2) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.MinSum() == v1);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
